# no invented proof; drivers = rest stops only. Every stat below is from a linked, checked source.

def ph(pid, by, slug, alt, cap, pos=None):
    d = {'id': pid, 'by': by, 'href': f'https://unsplash.com/photos/{slug}', 'alt': alt, 'cap': cap}
    if pos: d['pos'] = pos
    return d

